const fs=require('fs');
const {chromium}=require('playwright');
const {Document,Packer,Paragraph,TextRun,ImageRun,AlignmentType,HeadingLevel,PageBreak,Footer,Header,Table,TableRow,TableCell,WidthType,BorderStyle,VerticalAlign}=require('docx');
const P='C:/Users/UJAH/.cache/codex-runtimes/codex-primary-runtime/dependencies/node/node_modules';
const D=require(P+'/docx');
const root='C:/Users/UJAH/advanced-database-portfolio/';
const OUT=root+'output/';
const para=(text,opt={})=>new D.Paragraph({text,spacing:{after:105,line:245},...opt});
const head=(text)=>new D.Paragraph({text,heading:D.HeadingLevel.HEADING_1,spacing:{before:150,after:60},keepNext:true});
const cap=(text)=>new D.Paragraph({text,alignment:D.AlignmentType.CENTER,spacing:{after:110},children:[new D.TextRun({text,italics:true,size:16,color:'586572'})]});
function img(rel,w=520){return new D.Paragraph({alignment:D.AlignmentType.CENTER,spacing:{after:10,before:15},children:[new D.ImageRun({data:fs.readFileSync(root+rel),transformation:{width:w,height:Math.round(w*0.52)}})]})}
function fig(rel,text,w=520){return [img(rel,w),cap(text)]}
function twofig(items){let cells=items.map(([rel,text])=>new D.TableCell({width:{size:50,type:D.WidthType.PERCENTAGE},verticalAlign:D.VerticalAlign.CENTER,borders:{top:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},bottom:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},left:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},right:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'}},children:[new D.Paragraph({alignment:D.AlignmentType.CENTER,children:[new D.ImageRun({data:fs.readFileSync(root+rel),transformation:{width:320,height:155}})]}),new D.Paragraph({alignment:D.AlignmentType.CENTER,spacing:{after:70},children:[new D.TextRun({text,italics:true,size:15,color:'586572'})]})]}));return new D.Table({width:{size:100,type:D.WidthType.PERCENTAGE},columnWidths:[4680,4680],rows:[new D.TableRow({children:cells})],borders:{top:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},bottom:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},left:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},right:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},insideH:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'},insideV:{style:D.BorderStyle.NONE,size:0,color:'FFFFFF'}}})}
const kids=[];
kids.push(new D.Paragraph({text:'Advanced Database Systems Portfolio',heading:D.HeadingLevel.TITLE,spacing:{after:20}}));
kids.push(new D.Paragraph({text:'Individual practical assessment summary',spacing:{after:100},children:[new D.TextRun({text:'Individual practical assessment summary',size:22,color:'485765'})]}));
kids.push(new D.Table({width:{size:100,type:D.WidthType.PERCENTAGE},columnWidths:[4680,4680],rows:[['Student  Osimen Odigie','Course  MIT 8103 Advanced Database Systems'],['Student ID  301826111','Session  2026/2027, First Semester']].map(a=>new D.TableRow({children:a.map(x=>new D.TableCell({shading:{fill:'EAF0F5'},margins:{top:60,bottom:60,left:110,right:110},children:[new D.Paragraph({text:x,spacing:{after:0},style:'small'})]}))}))}));
kids.push(head('Case study and scope'),para('I used a Brazilian online marketplace based on the public Olist e-commerce dataset. Customers place orders for products offered by sellers, make one or more payments, receive deliveries and leave reviews. The database supports order processing, stock changes, customer and seller lookups, sales reporting and order history. My portfolio follows this same case study through relational design, query tuning, transaction control, document modelling and cloud distribution.'));
kids.push(head('Portfolio 1  Relational design and data quality'),para('I built a MySQL schema with nine related tables for customers, orders, items, payments, reviews, products, sellers, category translations and geolocation. Primary and foreign keys protect relationships, while constraints reject invalid values. I separated order items and payments because combining them in one flat table can multiply rows and overstate totals. The design reaches third normal form for most transactional tables. I documented specific exceptions where the supplied data prevented stricter normalization, including customer postcodes absent from the geolocation table. The loaded database contains about 99,441 orders and 1,000,163 geolocation rows. The ER model and row-count screenshots support the schema and load checks.'));
kids.push(...fig('P1-database-design/P1-database-designer-diagram.png','Figure 1. Relational entities and key relationships in the marketplace model.',580));
kids.push(head('Portfolio 2  Query processing and optimisation'),para('I tested eight reporting queries with MySQL EXPLAIN ANALYZE and added six indexes chosen for the filters, joins and grouping used by the workload. The clearest example was the one-postcode geolocation query: a covering index reduced the rows examined from one million to 103, with median execution time falling from 1.88 seconds to about 0.17 milliseconds on this machine. Results varied by query. A control query that had no relevant new index did not improve on its first run, although later warm runs were faster. This showed me that caching can look like an indexing gain. I therefore interpreted timings alongside execution plans and marked the machine-specific results as indicative rather than universal.'));
kids.push(...fig('P2-query-optimisation/evidence06-indexes-created.png','Figure 2. MySQL output confirming creation of the workload indexes.',520));
kids.push(head('Portfolio 3  Transactions and concurrency'),para('I added a small stock table to model checkout because stock quantities are not present in the source dataset. With InnoDB, I demonstrated that a failed checkout can roll back its order, item and stock changes together. Two-session tests showed a dirty read under READ UNCOMMITTED, a non-repeatable read under READ COMMITTED and snapshot behaviour under REPEATABLE READ. I also reproduced a lost update: two sessions each sold from a stock value of ten, but the final value became nine instead of eight. SELECT FOR UPDATE and an atomic conditional UPDATE prevented that error. A separate deadlock test showed InnoDB detecting a lock cycle and rolling back one transaction. These exercises made clear that a correct stock decision must be checked and applied as one protected operation.'));
kids.push(...fig('P3-transactions-concurrency/Window B Rollback error.png','Figure 3. Session evidence of InnoDB identifying and resolving a deadlock.',500));
kids.push(head('Portfolio 4  NoSQL document model'),para('I exported the relational data to JSON and loaded it into MongoDB Atlas. Each order document embeds its bounded items, payments, reviews and a customer snapshot, so a common order-history read does not need several joins. Products and sellers remain separate because they are shared by many orders. I queried arrays and used aggregation pipelines for revenue, reviews and seller results. A compound index supported cancelled-order date searches, and schema validation rejected an invalid status. The orders collection contains a 20,000-order sample, while product and seller collections contain all records. This model makes complete order reads convenient, but cross-document integrity and reports spanning many entities remain easier to manage relationally.'));
kids.push(...fig('P4-nosql/Orders imported.png','Figure 4. MongoDB Compass evidence of the imported order documents.',520));
kids.push(head('Portfolio 5  Cloud distribution and design'),para('I deployed the MongoDB document model to an AWS Paris Atlas free cluster and observed a three-member replica set with one primary and two secondaries. In the write-concern runs, writes from Lagos took roughly 185 milliseconds on average. The measured difference between w:1 and majority was too small to separate from run-to-run variation, so these tests do not establish that both guarantees have identical costs in other conditions. At the measured document size, the full order data is estimated at about 80 MB. Sharding is therefore unnecessary for this dataset. If growth later justified it, I recommend a hashed customer unique ID key because it should distribute the observed customer workload while keeping one customer’s order history on one shard. Sharding and failover were not run on the free tier; these remain reasoned design proposals.'));
kids.push(...fig('P5-distributed-cloud/C replica set health.png','Figure 5. Atlas replica-set health evidence from the deployed cluster.',520));
kids.push(head('Technical reflection'),para('The most useful lesson for me was that database choices depend on how the data is read and changed. Normalization reduced repeated facts in MySQL, while embedding selected order data made MongoDB reads simpler. Neither design is automatically best for every task. The transaction exercises were especially useful because the lost update looked harmless in a single session but produced the wrong stock count under concurrency. I also learned to be careful with performance claims: a plan can show fewer rows examined, while elapsed time is still affected by cache state, network distance and the machine. My next improvement would be to run isolated repeated benchmarks and to test the proposed cloud design on a tier that permits failover and sharding.'));
kids.push(head('Repository, references and AI use'),para('The scripts, analyses, raw plans and supporting screenshots are organized in the project repository: https://github.com/odigieosimen/advanced-database-portfolio . The case study uses the Brazilian E-Commerce Public Dataset by Olist, distributed through Kaggle under CC BY-NC-SA 4.0. Technical references include the MySQL 8.0 Reference Manual, MongoDB Manual and MongoDB Atlas documentation. Tools used in the implementation include MySQL Community Server, MySQL Workbench, MongoDB Compass and MongoDB Atlas.'));
kids.push(para('AI use declaration: OpenAI Codex assisted in organizing evidence and drafting this summary from the assignment brief and portfolio files. I must review the wording, confirm every description against my own work, and be able to explain the scripts, results and design decisions before submission. The implementation evidence and measurements are from the project repository.'));
const doc=new D.Document({styles:{default:{document:{run:{font:'Calibri',size:19,color:'232B34'},paragraph:{spacing:{line:245,after:100}}}},paragraphStyles:[{id:'small',name:'Small',run:{font:'Calibri',size:16,color:'23303C'},paragraph:{spacing:{after:0}}}]},sections:[{properties:{page:{size:{width:12240,height:15840},margin:{top:730,bottom:730,left:960,right:960,header:300,footer:300}}},headers:{default:new D.Header({children:[new D.Paragraph({alignment:D.AlignmentType.RIGHT,children:[new D.TextRun({text:'MIT 8103  |  ADVANCED DATABASE SYSTEMS',bold:true,size:15,color:'65717C'})]})]})},footers:{default:new D.Footer({children:[new D.Paragraph({alignment:D.AlignmentType.CENTER,children:[new D.TextRun({text:'Osimen Odigie  •  301826111  •  2026/2027',size:15,color:'65717C'})]})]})},children:kids}]});
(async()=>{const buffer=await D.Packer.toBuffer(doc);fs.writeFileSync(OUT+'MIT8103_Advanced_Database_Portfolio_Report.docx',buffer);const browser=await chromium.launch({headless:true,executablePath:'C:/Program Files/Google/Chrome/Application/chrome.exe',args:['--no-sandbox','--disable-gpu']});const page=await browser.newPage();await page.setContent('<!doctype html><html><head><style>@page{size:letter;margin:.68in .68in}.top{font:9pt Calibri;color:#232b34;line-height:1.02}h1{font:700 12.5pt Calibri;margin:7pt 0 3pt;break-after:avoid}h2{font:700 21pt Calibri;margin:0}p{margin:0 0 4pt}figure{margin:2pt auto;text-align:center;break-inside:avoid}figure img{max-width:6.9in;max-height:2.0in;object-fit:contain}figcaption{font:italic 8pt Calibri;color:#4b5560;margin:0 0 3pt}header,footer{position:fixed;font:8pt Calibri;color:#65717c;left:0;right:0}header{position:absolute;top:.15in;text-align:right}footer{position:absolute;bottom:.12in;text-align:center}.meta{background:#eaf0f5;padding:4pt 8pt;display:grid;grid-template-columns:1fr 1fr;gap:4pt;font:8pt Calibri;margin-bottom:4pt}</style></head><body><header>MIT 8103  |  ADVANCED DATABASE SYSTEMS</header><footer>Osimen Odigie  •  301826111  •  2026/2027</footer><div class="top"><h2>Advanced Database Systems Portfolio</h2><p style="font-size:11pt;color:#485765;margin-bottom:5pt">Individual practical assessment summary</p><div class="meta"><div><b>Student</b>　Osimen Odigie</div><div><b>Course</b>　MIT 8103 Advanced Database Systems</div><div><b>Student ID</b>　301826111</div><div><b>Session</b>　2026/2027, First Semester</div></div><h1>Case study and scope</h1><p>I used a Brazilian online marketplace based on the public Olist e-commerce dataset. Customers place orders for products offered by sellers, make one or more payments, receive deliveries and leave reviews. The database supports order processing, stock changes, customer and seller lookups, sales reporting and order history. My portfolio follows this same case study through relational design, query tuning, transaction control, document modelling and cloud distribution.</p><h1>Portfolio 1　Relational design and data quality</h1><p>I built a MySQL schema with nine related tables for customers, orders, items, payments, reviews, products, sellers, category translations and geolocation. Primary and foreign keys protect relationships, while constraints reject invalid values. I separated order items and payments because combining them in one flat table can multiply rows and overstate totals. The design reaches third normal form for most transactional tables. I documented specific exceptions where the supplied data prevented stricter normalization, including customer postcodes absent from the geolocation table. The loaded database contains about 99,441 orders and 1,000,163 geolocation rows. The ER model and row-count screenshots support the schema and load checks.</p><figure><img src="data:image/png;base64,"><figcaption>Figure 1. Relational entities and key relationships in the marketplace model.</figcaption></figure><h1>Portfolio 2　Query processing and optimisation</h1><p>I tested eight reporting queries with MySQL EXPLAIN ANALYZE and added six indexes chosen for the filters, joins and grouping used by the workload. The clearest example was the one-postcode geolocation query: a covering index reduced the rows examined from one million to 103, with median execution time falling from 1.88 seconds to about 0.17 milliseconds on this machine. Results varied by query. A control query that had no relevant new index did not improve on its first run, although later warm runs were faster. This showed me that caching can look like an indexing gain. I therefore interpreted timings alongside execution plans and marked the machine-specific results as indicative rather than universal.</p><figure><img src="data:image/png;base64,"><figcaption>Figure 2. MySQL output confirming creation of the workload indexes.</figcaption></figure><h1>Portfolio 3　Transactions and concurrency</h1><p>I added a small stock table to model checkout because stock quantities are not present in the source dataset. With InnoDB, I demonstrated that a failed checkout can roll back its order, item and stock changes together. Two-session tests showed a dirty read under READ UNCOMMITTED, a non-repeatable read under READ COMMITTED and snapshot behaviour under REPEATABLE READ. I also reproduced a lost update: two sessions each sold from a stock value of ten, but the final value became nine instead of eight. SELECT FOR UPDATE and an atomic conditional UPDATE prevented that error. A separate deadlock test showed InnoDB detecting a lock cycle and rolling back one transaction. These exercises made clear that a correct stock decision must be checked and applied as one protected operation.</p><figure><img src="data:image/png;base64,"><figcaption>Figure 3. Session evidence of InnoDB identifying and resolving a deadlock.</figcaption></figure><h1>Portfolio 4　NoSQL document model</h1><p>I exported the relational data to JSON and loaded it into MongoDB Atlas. Each order document embeds its bounded items, payments, reviews and a customer snapshot, so a common order-history read does not need several joins. Products and sellers remain separate because they are shared by many orders. I queried arrays and used aggregation pipelines for revenue, reviews and seller results. A compound index supported cancelled-order date searches, and schema validation rejected an invalid status. The orders collection contains a 20,000-order sample, while product and seller collections contain all records. This model makes complete order reads convenient, but cross-document integrity and reports spanning many entities remain easier to manage relationally.</p><figure><img src="data:image/png;base64,"><figcaption>Figure 4. MongoDB Compass evidence of the imported order documents.</figcaption></figure><h1>Portfolio 5　Cloud distribution and design</h1><p>I deployed the MongoDB document model to an AWS Paris Atlas free cluster and observed a three-member replica set with one primary and two secondaries. In the write-concern runs, writes from Lagos took roughly 185 milliseconds on average. The measured difference between w:1 and majority was too small to separate from run-to-run variation, so these tests do not establish that both guarantees have identical costs in other conditions. At the measured document size, the full order data is estimated at about 80 MB. Sharding is therefore unnecessary for this dataset. If growth later justified it, I recommend a hashed customer unique ID key because it should distribute the observed customer workload while keeping one customer’s order history on one shard. Sharding and failover were not run on the free tier; these remain reasoned design proposals.</p><figure><img src="data:image/png;base64,"><figcaption>Figure 5. Atlas replica-set health evidence from the deployed cluster.</figcaption></figure><h1>Technical reflection</h1><p>The most useful lesson for me was that database choices depend on how the data is read and changed. Normalization reduced repeated facts in MySQL, while embedding selected order data made MongoDB reads simpler. Neither design is automatically best for every task. The transaction exercises were especially useful because the lost update looked harmless in a single session but produced the wrong stock count under concurrency. I also learned to be careful with performance claims: a plan can show fewer rows examined, while elapsed time is still affected by cache state, network distance and the machine. My next improvement would be to run isolated repeated benchmarks and to test the proposed cloud design on a tier that permits failover and sharding.</p><h1>Repository, references and AI use</h1><p>The scripts, analyses, raw plans and supporting screenshots are organized in the project repository: https://github.com/odigieosimen/advanced-database-portfolio . The case study uses the Brazilian E-Commerce Public Dataset by Olist, distributed through Kaggle under CC BY-NC-SA 4.0. Technical references include the MySQL 8.0 Reference Manual, MongoDB Manual and MongoDB Atlas documentation. Tools used in the implementation include MySQL Community Server, MySQL Workbench, MongoDB Compass and MongoDB Atlas.</p><p>AI use declaration: OpenAI Codex assisted in organizing evidence and drafting this summary from the assignment brief and portfolio files. I must review the wording, confirm every description against my own work, and be able to explain the scripts, results and design decisions before submission. The implementation evidence and measurements are from the project repository.</p></div></body></html>');await page.pdf({path:OUT+'MIT8103_Advanced_Database_Portfolio_Report.pdf',format:'Letter',printBackground:true,preferCSSPageSize:true});await page.screenshot({path:OUT+'pdf_preview.png',fullPage:true});console.log('PDF written');await browser.close()})().catch(e=>{console.error(e);process.exit(1)});


